
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_revm06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_revm06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.523386238922924e-02, -8.447653132817629e-02, -8.338078841494240e-02, -8.179165809477487e-02, -7.947973967262227e-02, -7.610339608737175e-02, -7.115375273473633e-02, -6.388141517799370e-02, -5.314361106773979e-02, -3.669244158335919e-02, -2.194221365699767e-02, -6.111478503710784e-02, -3.886407029613004e-02, -2.868443222987239e-02, -1.560761358211607e-02, 9.207773600673392e-03, 2.824543824186811e-02, 1.036800675994366e-02, 1.127378333567674e-03, 3.929569999991903e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


